        // 辅助：智能解析并转换外部/插件备份包为标准 entries 与附加表数据
        const parseUniversalBackupPackage = async (data) => {
            if (!data || typeof data !== 'object') throw new Error('无效的备份文件数据');
            let entries = [];
            let extraDatabases = {};
            let webStorage = {};
            let isPluginFormat = false;

            // 分支 A: 原生 APP 扁平备份格式
            if (data.type === 'rp-hub-complete-backup' && Array.isArray(data.entries)) {
                entries = data.entries.slice();
                if (data.databases && typeof data.databases === 'object') extraDatabases = data.databases;
                if (data.webStorage && typeof data.webStorage === 'object') webStorage = data.webStorage;
            }
            // 分支 B: 柳贯一插件流式 JSON（v8+）: { __rphub_backup__: 1, databases: { RPHubDB: { store: [ {k, v} ] } }, webStorage }
            else if (data.__rphub_backup__ || (data.databases && typeof data.databases === 'object' && !Array.isArray(data.databases))) {
                isPluginFormat = true;
                const dbs = data.databases || {};
                extraDatabases = dbs;
                webStorage = data.webStorage || {};

                // 提取 RPHubDB / main 库
                const mainStore = (dbs.RPHubDB && dbs.RPHubDB.store) || (dbs.main) || [];
                if (Array.isArray(mainStore)) {
                    mainStore.forEach(rec => {
                        if (rec && typeof rec === 'object') {
                            const k = rec.k !== undefined ? rec.k : rec.key;
                            const v = rec.v !== undefined ? rec.v : rec.value;
                            if (k !== undefined) entries.push({ key: String(k), value: v });
                        }
                    });
                } else if (typeof mainStore === 'object') {
                    Object.keys(mainStore).forEach(k => {
                        entries.push({ key: String(k), value: mainStore[k] });
                    });
                }

                // 提取 localStorage
                if (webStorage && webStorage.localStorage && typeof webStorage.localStorage === 'object') {
                    Object.keys(webStorage.localStorage).forEach(lk => {
                        entries.push({ key: LOCAL_BACKUP_PREFIX + lk, value: webStorage.localStorage[lk] });
                    });
                }
            } else {
                throw new Error('不是支持的 RP-Hub 或扩展备份格式');
            }

            return { entries, extraDatabases, webStorage, isPluginFormat };
        };

        // 辅助：将备份中携带的名场面库还原到本地对应 IndexedDB（2.8.19：留声机已下线）
        const restoreCompanionDatabases = async (extraDbs) => {
            if (!extraDbs || typeof extraDbs !== 'object') return;
            // 2.8.19：留声机功能已下线（用户决定），备份不再携带其数据；这里也不再还原。
            // 旧备份里若含 sakura_gramophone_db 会被静默忽略（该库的数据本身不动）。
            // 1. 名场面手记 (支持 sf_moments_db / moments 与 SakuraMomentsDB / moments)
            const mmData = (extraDbs.sf_moments_db && extraDbs.sf_moments_db.moments)
                        || (extraDbs.SakuraMomentsDB && extraDbs.SakuraMomentsDB.moments)
                        || (extraDbs.moments && extraDbs.moments.list);
            if (mmData) {
                try {
                    let list = [];
                    if (Array.isArray(mmData)) {
                        list = mmData.map(item => (item && typeof item === 'object' && item.v !== undefined ? item.v : item));
                    } else if (typeof mmData === 'object' && Array.isArray(mmData.list)) {
                        list = mmData.list;
                    }
                    if (list.length) {
                        await new Promise((resolve) => {
                            const req = indexedDB.open('sf_moments_db', 1);
                            req.onupgradeneeded = e => {
                                const db = e.target.result;
                                if (!db.objectStoreNames.contains('moments')) db.createObjectStore('moments');
                            };
                            req.onsuccess = e => {
                                const db = e.target.result;
                                const tx = db.transaction(['moments'], 'readwrite');
                                tx.objectStore('moments').put(list, 'list');
                                tx.oncomplete = () => { db.close(); resolve(); };
                                tx.onerror = () => { db.close(); resolve(); };
                            };
                            req.onerror = () => resolve();
                        });
