                        entries.push({ key: LOCAL_BACKUP_PREFIX + k, value: lsData[k] });
                    });
                } catch (e) {
                    console.warn('[ZIP Import] 解析 localStorage.json 失败:', e);
                }
            }

            // 2. 遍历各数据库及其分块 chunk
            const databases = manifest.databases || [];
