                            if (rec && typeof rec === 'object') {
                                const k = rec.k !== undefined ? rec.k : rec.key;
                                const v = rec.v !== undefined ? rec.v : rec.value;
                                if (k !== undefined) entries.push({ key: String(k), value: v });
                            }
                        });
                    }
                }
            }

            return {
                entries,
                extraDatabases,
                webStorage,
                isPluginFormat: true,
                isZipFormat: true,
