                        + fmtMB(getRestoreBudget().maxFileBytes) + '）。继续导入有失败甚至闪退的风险。仍要尝试吗？',
                        { confirmText: '仍然导入' }).then(function (goOn) { if (goOn) startJsonRead(); });
                } else {
                    startJsonRead();
                }
            }
        };
