        }
        if (gapStart) gaps.push([gapStart, auditableMax]);
        gaps.forEach(([from, to]) => {
            issues.push({
                level: 'warn', tag: '缺总结',
                where: from === to ? `第 ${from} 轮` : `第 ${from}–${to} 轮`,
                text: `这一段没有被任何记忆覆盖，共 ${to - from + 1} 轮。已过保留楼层仍未覆盖，说明总结没有补全。`
